package com.shopsmart.api;
import com.shopsmart.api.ApiDtos.OrderResponse;import com.shopsmart.service.OrderService;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/orders") @SecurityRequirement(name="bearerAuth") public class OrderController {private final OrderService orders;public OrderController(OrderService o){orders=o;}@PostMapping public OrderResponse checkout(Authentication a){return ApiMapper.order(orders.checkout(a.getName()));}@GetMapping public List<OrderResponse> mine(Authentication a){return orders.mine(a.getName()).stream().map(ApiMapper::order).toList();}@GetMapping("/{id}") public OrderResponse get(@PathVariable Long id,Authentication a){return ApiMapper.order(orders.getMine(a.getName(),id));}@PostMapping("/{id}/cancel") public OrderResponse cancel(@PathVariable Long id,Authentication a){return ApiMapper.order(orders.cancel(a.getName(),id));}}
